                name: "「私は…たくさん聞きたいことがある。ただ…どうして？なぜ？<br>\r\n                みんなにお別れを言っていたのに…本当にみんないなくなったの。<br>\r\n                放送の断片から…ある程度は何が起きたか理解したつもり。たぶん…戦争だったのね。<br>\r\n                そしてどういうわけか…これが生き残った世界。今は言葉にすらできないわ。」",
